def format_time(mtime):
    return time.strftime("%Y-%m-%d %H:%M", time.localtime(mtime))

def main(stdscr):
    curses.curs_set(0)
    stdscr.nodelay(False)

    path = os.path.abspath(sys.argv[1] if len(sys.argv) > 1 else '.')
    state = parse_session()

    idx = 0

    while True:
        stdscr.erase()
        h, w = stdscr.getmaxyx()

        dirs, files = get_entries(path, state['show_hidden'])
        all_entries = dirs + files
        total = len(all_entries)

        if total > 0:
            idx = max(0, min(idx, total - 1))
        else:
            idx = 0

        # Top bar
        git_branch = None
        head_file = os.path.join(path, '.git', 'HEAD')
        if os.path.exists(head_file):
            try:
                with open(head_file, 'r') as f:
                    content = f.read().strip()
                if content.startswith('ref: refs/heads/'):
                    git_branch = content.split('/')[-1]
            except:
                pass

        title = f" {path}"
        if git_branch:
            title += f" on {git_branch}"

        if total > 0:
            current_name = all_entries[idx]
            right_title = f"[{current_name}]"
        else:
            current_name = None
            right_title = ""

        if state['preview']:
            left_w = w // 2
            right_w = w - left_w
        else:
            left_w = w

        # draw title
        stdscr.addstr(0, 0, title)
        if right_title:
            if state['preview']:
                stdscr.addstr(0, left_w + 1, right_title)
            else:
                # in full width without preview, right title doesn't seem to be drawn? Wait, let's check
                pass

        # draw entries
        list_h = h - 3
        start_idx = max(0, idx - list_h // 2) if total > list_h else 0

        for i in range(min(list_h, total - start_idx)):
            curr_i = start_idx + i
            name = all_entries[curr_i]
            full_p = os.path.join(path, name)
            try:
                st = os.stat(full_p)
                mtime = format_time(st.st_mtime)
            except:
                mtime = ""

            prefix = "> " if curr_i == idx else "  "

            # format line
            name_max = left_w - 2 - 17 # 16 for date + 1 space
            disp_name = name[:name_max]

            line = f"{prefix}{disp_name}"
            pad = left_w - len(line) - len(mtime)
            if pad > 0:
                line += " " * pad
            line += mtime

            try:
                stdscr.addstr(2 + i, 0, line[:left_w])
            except curses.error:
                pass

        # draw bottom bar
        if total > 0:
            try:
                st = os.stat(os.path.join(path, current_name))
                size = format_size(st.st_size)
                perms = oct(st.st_mode & 0o777)[2:]

                ext = ""
                if not os.path.isdir(os.path.join(path, current_name)):
                    if '.' in current_name and not current_name.startswith('.') or current_name.count('.') > 1:
                        ext = current_name.split('.')[-1] + " "

                bot = f" {idx+1}/{total} {ext}{size} {perms}"
                stdscr.addstr(h-1, 0, bot)
            except:
                pass

        stdscr.refresh()

        c = stdscr.getch()
        if c == ord('q'): # wait, what about :q ?
            pass
        elif c == ord('j') or c == curses.KEY_DOWN:
            idx += 1
        elif c == ord('k') or c == curses.KEY_UP:
            idx -= 1
        elif c == ord('h') or c == curses.KEY_LEFT:
            path = os.path.dirname(path)
            idx = 0
        elif c == ord('l') or c == curses.KEY_RIGHT or c == 10:
            if total > 0:
                full_p = os.path.join(path, all_entries[idx])
                if os.path.isdir(full_p):
                    path = full_p
                    idx = 0
                else:
                    # open file
                    pass
        elif c == ord('v'):
            state['preview'] = not state['preview']
            save_session(state)
        elif c == ord(':'):
            # rudimentary command line
            stdscr.addstr(h-1, 0, ":" + " "*(w-2))
            stdscr.move(h-1, 1)
            curses.curs_set(1)
            curses.echo()
            cmd = stdscr.getstr(h-1, 1).decode('utf-8')
            curses.noecho()
            curses.curs_set(0)
            if cmd == 'q':
                break

if __name__ == '__main__':
    if '--help' in sys.argv or '-h' in sys.argv:
        with open('help.txt', 'r') as f:
            print(f.read(), end='')
        sys.exit(0)
    if '--init' in sys.argv:
        with open('init.txt', 'r') as f:
            print(f.read(), end='')
        sys.exit(0)
    curses.wrapper(main)
